import { shadows } from '@advui/theme'
import { forwardRef } from 'react'
import {
  SwitchFrame as TamaguiSwitchFrame,
  type SwitchProps as TamaguiSwitchProps,
  SwitchThumb as TamaguiSwitchThumb,
  type TamaguiElement,
  createSwitch,
  isWeb,
  styled,
} from 'tamagui/unstyled'
import { useControllableState } from '../../hooks/useControllableState'
import { type FieldControlProps, useFieldControl } from '../../hooks/useFieldControl'
import { ariaState } from '../../utils/ariaState'
import { colorsOpacity } from '../../utils/transition'

const Frame = styled(TamaguiSwitchFrame, {
  displayName: 'Switch',
  justifyContent: 'center',
  // reset the UA <button> padding so the thumb travel is exact
  padding: 0,
  cursor: 'pointer',
  borderRadius: 'full',
  borderWidth: 2,
  borderColor: 'transparent',
  backgroundColor: 'input',
  transition: colorsOpacity('quick'),
  outlineColor: 'focus-visible:ring',
  outlineStyle: 'focus-visible:solid',
  outlineWidth: 'focus-visible:2px',
  outlineOffset: 'focus-visible:2px',

  variants: {
    size: {
      sm: {
        width: '9',
        height: '5',
        minHeight: '5',
      },
      md: {
        width: '11',
        height: '6',
        minHeight: '6',
      },
    },
    disabled: {
      true: { opacity: 0.5, cursor: 'not-allowed', pointerEvents: isWeb ? 'none' : 'auto' },
    },
  } as const,

  defaultVariants: { size: 'md' },
})

const Thumb = styled(TamaguiSwitchThumb, {
  displayName: 'SwitchThumb',
  backgroundColor: 'background',
  borderRadius: 'full',
  // The thumb slides with a transform.
  transition: colorsOpacity('quick', 'transform'),
  ...shadows.xs,

  variants: {
    size: {
      sm: {
        width: '4',
        height: '4',
      },
      md: {
        width: '5',
        height: '5',
      },
    },
  } as const,

  defaultVariants: { size: 'md' },
})

const BaseSwitch = createSwitch({ Frame, Thumb })

export interface SwitchProps extends Omit<TamaguiSwitchProps, 'size'> {
  size?: 'sm' | 'md'
}

/**
 * On/off toggle for settings that apply immediately. Exposes the `switch` role
 * with checked state; Space/Enter toggle it on web.
 */
export const Switch = forwardRef<TamaguiElement, SwitchProps>(function Switch(switchProps, ref) {
  // `invalid` only comes from a Field; a switch has no error style of its own.
  const {
    size = 'md',
    invalid,
    checked: checkedProp,
    defaultChecked = false,
    onCheckedChange,
    ...props
  } = useFieldControl<SwitchProps & FieldControlProps>(switchProps)
  // Tamagui's switch sends its checked and disabled states on web only, so the
  // value is held here and native gets both as states of an accessibility element.
  const [checked, setChecked] = useControllableState({
    value: checkedProp,
    defaultValue: defaultChecked,
    onChange: onCheckedChange,
  })
  return (
    <BaseSwitch
      ref={ref}
      role="switch"
      size={size as never}
      activeStyle={{ backgroundColor: 'primary' }}
      aria-invalid={invalid || undefined}
      {...props}
      checked={checked}
      onCheckedChange={setChecked}
      {...(isWeb
        ? null
        : {
            accessible: true,
            'aria-checked': checked,
            'aria-disabled': ariaState(props.disabled),
          })}
    >
      <BaseSwitch.Thumb size={size as never} />
    </BaseSwitch>
  )
})
